import azure.cognitiveservices.speech as speechsdk
import queue

def stream_microphone(payload, config=None):
    config = config or {}
    class SpeechStreamer:
        def __init__(self, config):
            speech_key = os.environ.get("SPEECH_KEY")
            speech_region = os.environ.get("SPEECH_REGION")
            speech_config = speechsdk.SpeechConfig(subscription=speech_key, region=speech_region)
            speech_config.speech_recognition_language = config.get("language", "en-US")

            audio_config = speechsdk.audio.AudioConfig(use_default_microphone=True)
            self.speech_recognizer = speechsdk.SpeechRecognizer(speech_config=speech_config, audio_config=audio_config)

            self.q = queue.Queue()

            self.speech_recognizer.recognizing.connect(lambda evt: self.q.put(evt.result.text))
            self.speech_recognizer.recognized.connect(lambda evt: self.q.put(evt.result.text))

            def stop_cb(evt):
                self.speech_recognizer.stop_continuous_recognition()
                self.q.put(None)

            self.speech_recognizer.session_stopped.connect(stop_cb)
            self.speech_recognizer.canceled.connect(stop_cb)

        def __iter__(self):
            self.speech_recognizer.start_continuous_recognition()
            while True:
                item = self.q.get()
                if item is None:
                    break
                if item:
                    yield item

    result = SpeechStreamer(config)
    return result
